#include "wifi_board.h"
#include "codecs/es8311_audio_codec.h"
#include "display/lcd_display.h"
#include "application.h"
#include "button.h"
#include "config.h"
#include "mcp_server.h"

#include <esp_log.h>
#include <driver/i2c_master.h>
#include <driver/spi_common.h>

#define TAG "MyCustomBoard"

class MyCustomBoard : public WifiBoard {
private:
    i2c_master_bus_handle_t codec_i2c_bus_;
    Button boot_button_;
    LcdDisplay* display_;

    // I2C初始化
    void InitializeI2c() {
        i2c_master_bus_config_t i2c_bus_cfg = {
            .i2c_port = I2C_NUM_0,
            .sda_io_num = AUDIO_CODEC_I2C_SDA_PIN,
            .scl_io_num = AUDIO_CODEC_I2C_SCL_PIN,
            .clk_source = I2C_CLK_SRC_DEFAULT,
            .glitch_ignore_cnt = 7,
            .intr_priority = 0,
            .trans_queue_depth = 0,
            .flags = {
                .enable_internal_pullup = 1,
            },
        };
        ESP_ERROR_CHECK(i2c_new_master_bus(&i2c_bus_cfg, &codec_i2c_bus_));
    }

    // SPI初始化（用于显示屏）
    void InitializeSpi() {
        spi_bus_config_t buscfg = {};
        buscfg.mosi_io_num = DISPLAY_SPI_MOSI_PIN;
        buscfg.miso_io_num = GPIO_NUM_NC;
        buscfg.sclk_io_num = DISPLAY_SPI_SCK_PIN;
        buscfg.quadwp_io_num = GPIO_NUM_NC;
        buscfg.quadhd_io_num = GPIO_NUM_NC;
        buscfg.max_transfer_sz = DISPLAY_WIDTH * DISPLAY_HEIGHT * sizeof(uint16_t);
        ESP_ERROR_CHECK(spi_bus_initialize(SPI2_HOST, &buscfg, SPI_DMA_CH_AUTO));
    }

    // 按钮初始化
    void InitializeButtons() {
        boot_button_.OnClick([this]() {
            auto& app = Application::GetInstance();
            if (app.GetDeviceState() == kDeviceStateStarting) {
                EnterWifiConfigMode();
                return;
            }
            app.ToggleChatState();
        });
    }

    // 显示屏初始化（以ST7789为例）
    void InitializeDisplay() {
        esp_lcd_panel_io_handle_t panel_io = nullptr;
        esp_lcd_panel_handle_t panel = nullptr;

        esp_lcd_panel_io_spi_config_t io_config = {};
        io_config.cs_gpio_num = DISPLAY_SPI_CS_PIN;
        io_config.dc_gpio_num = DISPLAY_DC_PIN;
        io_config.spi_mode = 2;
        io_config.pclk_hz = 80 * 1000 * 1000;
        io_config.trans_queue_depth = 10;
        io_config.lcd_cmd_bits = 8;
        io_config.lcd_param_bits = 8;
        ESP_ERROR_CHECK(esp_lcd_new_panel_io_spi(SPI2_HOST, &io_config, &panel_io));

        esp_lcd_panel_dev_config_t panel_config = {};
        panel_config.reset_gpio_num = GPIO_NUM_NC;
        panel_config.rgb_ele_order = LCD_RGB_ELEMENT_ORDER_RGB;
        panel_config.bits_per_pixel = 16;
        ESP_ERROR_CHECK(esp_lcd_new_panel_st7789(panel_io, &panel_config, &panel));

        esp_lcd_panel_reset(panel);
        esp_lcd_panel_init(panel);
        esp_lcd_panel_invert_color(panel, true);
        esp_lcd_panel_swap_xy(panel, DISPLAY_SWAP_XY);
        esp_lcd_panel_mirror(panel, DISPLAY_MIRROR_X, DISPLAY_MIRROR_Y);

        // 创建显示屏对象
        display_ = new SpiLcdDisplay(panel_io, panel,
                                    DISPLAY_WIDTH, DISPLAY_HEIGHT, 
                                    DISPLAY_OFFSET_X, DISPLAY_OFFSET_Y, 
                                    DISPLAY_MIRROR_X, DISPLAY_MIRROR_Y, DISPLAY_SWAP_XY);
    }

    // MCP Tools 初始化
    void InitializeTools() {
        // 参考 MCP 文档
    }

public:
    // 构造函数
    MyCustomBoard() : boot_button_(BOOT_BUTTON_GPIO) {
        InitializeI2c();
        InitializeSpi();
        InitializeDisplay();
        InitializeButtons();
        InitializeTools();
        GetBacklight()->SetBrightness(100);
    }

    // 获取音频编解码器
    virtual AudioCodec* GetAudioCodec() override {
        static Es8311AudioCodec audio_codec(
            codec_i2c_bus_, 
            I2C_NUM_0, 
            AUDIO_INPUT_SAMPLE_RATE, 
            AUDIO_OUTPUT_SAMPLE_RATE,
            AUDIO_I2S_GPIO_MCLK, 
            AUDIO_I2S_GPIO_BCLK, 
            AUDIO_I2S_GPIO_WS, 
            AUDIO_I2S_GPIO_DOUT, 
            AUDIO_I2S_GPIO_DIN,
            AUDIO_CODEC_PA_PIN, 
            AUDIO_CODEC_ES8311_ADDR);
        return &audio_codec;
    }

    // 获取显示屏
    virtual Display* GetDisplay() override {
        return display_;
    }

    // 获取背光控制
    virtual Backlight* GetBacklight() override {
        static PwmBacklight backlight(DISPLAY_BACKLIGHT_PIN, DISPLAY_BACKLIGHT_OUTPUT_INVERT);
        return &backlight;
    }
};

// 注册开发板
DECLARE_BOARD(MyCustomBoard);

- **时机：** 后台 API 收到设备 "hello" 消息，确认设备支持 MCP 后，通常作为 MCP 会话的第一个请求发送。
- **发送方：** 后台 API (客户端)。
- **方法：** `initialize`
- **消息 (MCP payload):**

  ```json
  {
    "jsonrpc": "2.0",
    "method": "initialize",
    "params": {
      "capabilities": {
        // 客户端能力，可选

        // 摄像头视觉相关
        "vision": {
          "url": "...", //摄像头: 图片处理地址(必须是http地址, 不是websocket地址)
          "token": "..." // url token
        }

        // ... 其他客户端能力
      }
    },
    "id": 1 // 请求 ID
  }
  ```

- **设备响应时机：** 设备收到 `initialize` 请求并处理后。
- **设备响应消息 (MCP payload):**
  ```json
  {
    "jsonrpc": "2.0",
    "id": 1, // 匹配请求 ID
    "result": {
      "protocolVersion": "2024-11-05",
      "capabilities": {
        "tools": {} // 这里的 tools 似乎不列出详细信息，需要 tools/list
      },
      "serverInfo": {
        "name": "...", // 设备名称 (BOARD_NAME)
        "version": "..." // 设备固件版本
      }
    }
  }
  ```

- **时机：** 后台 API 需要获取设备当前支持的具体功能（工具）列表及其调用方式时。
- **发送方：** 后台 API (客户端)。
- **方法：** `tools/list`
- **消息 (MCP payload):**
  ```json
  {
    "jsonrpc": "2.0",
    "method": "tools/list",
    "params": {
      "cursor": "" // 用于分页，首次请求为空字符串
    },
    "id": 2 // 请求 ID
  }
  ```
- **设备响应时机：** 设备收到 `tools/list` 请求并生成工具列表后。
- **设备响应消息 (MCP payload):**
  ```json
  {
    "jsonrpc": "2.0",
    "id": 2, // 匹配请求 ID
    "result": {
      "tools": [ // 工具对象列表
        {
          "name": "self.get_device_status",
          "description": "...",
          "inputSchema": { ... } // 参数 schema
        },
        {
          "name": "self.audio_speaker.set_volume",
          "description": "...",
          "inputSchema": { ... } // 参数 schema
        }
        // ... 更多工具
      ],
      "nextCursor": "..." // 如果列表很大需要分页，这里会包含下一个请求的 cursor 值
    }
  }
  ```
- **分页处理：** 如果 `nextCursor` 字段非空，客户端需要再次发送 `tools/list` 请求，并在 `params` 中带上这个 `cursor` 值以获取下一页工具。

- **时机：** 后台 API 需要执行设备上的某个具体功能时。
- **发送方：** 后台 API (客户端)。
- **方法：** `tools/call`
- **消息 (MCP payload):**
  ```json
  {
    "jsonrpc": "2.0",
    "method": "tools/call",
    "params": {
      "name": "self.audio_speaker.set_volume", // 要调用的工具名称
      "arguments": {
        // 工具参数，对象格式
        "volume": 50 // 参数名及其值
      }
    },
    "id": 3 // 请求 ID
  }
  ```
- **设备响应时机：** 设备收到 `tools/call` 请求，执行相应的工具函数后。
- **设备成功响应消息 (MCP payload):**
  ```json
  {
    "jsonrpc": "2.0",
    "id": 3, // 匹配请求 ID
    "result": {
      "content": [
        // 工具执行结果内容
        { "type": "text", "text": "true" } // 示例：set_volume 返回 bool
      ],
      "isError": false // 表示成功
    }
  }
  ```
- **设备失败响应消息 (MCP payload):**
  ```json
  {
    "jsonrpc": "2.0",
    "id": 3, // 匹配请求 ID
    "error": {
      "code": -32601, // JSON-RPC 错误码，例如 Method not found (-32601)
      "message": "Unknown tool: self.non_existent_tool" // 错误描述
    }
  }
  ```

- **时机：** 设备内部发生需要通知后台 API 的事件时（例如，状态变化，虽然代码示例中没有明确的工具发送此类消息，但 `Application::SendMcpMessage` 的存在暗示了设备可能主动发送 MCP 消息）。
- **发送方：** 设备 (服务器)。
- **方法：** 可能是以 `notifications/` 开头的方法名，或者其他自定义方法。
- **消息 (MCP payload):** 遵循 JSON-RPC Notification 格式，没有 `id` 字段。
  ```json
  {
    "jsonrpc": "2.0",
    "method": "notifications/state_changed", // 示例方法名
    "params": {
      "newState": "idle",
      "oldState": "connecting"
    }
    // 没有 id 字段
  }
  ```
- **后台 API 处理：** 接收到 Notification 后，后台 API 进行相应的处理，但不回复。

void AddTool(
    const std::string& name,           // 工具名称，建议唯一且有层次感，如 self.dog.forward
    const std::string& description,    // 工具描述，简明说明功能，便于大模型理解
    const PropertyList& properties,    // 输入参数列表（可为空），支持类型：布尔、整数、字符串
    std::function<ReturnValue(const PropertyList&)> callback // 工具被调用时的回调实现
);

void InitializeTools() {
    auto& mcp_server = McpServer::GetInstance();
    // 例1：无参数，控制机器人前进
    mcp_server.AddTool("self.dog.forward", "机器人向前移动", PropertyList(), [this](const PropertyList&) -> ReturnValue {
        servo_dog_ctrl_send(DOG_STATE_FORWARD, NULL);
        return true;
    });
    // 例2：带参数，设置灯光 RGB 颜色
    mcp_server.AddTool("self.light.set_rgb", "设置RGB颜色", PropertyList({
        Property("r", kPropertyTypeInteger, 0, 255),
        Property("g", kPropertyTypeInteger, 0, 255),
        Property("b", kPropertyTypeInteger, 0, 255)
    }), [this](const PropertyList& properties) -> ReturnValue {
        int r = properties["r"].value<int>();
        int g = properties["g"].value<int>();
        int b = properties["b"].value<int>();
        led_on_ = true;
        SetLedColor(r, g, b);
        return true;
    });
}
